public class NullPointerExceptionDemo {
    static class Address { String city; }
    static class Customer { Address address; }
    static class Order { Customer customer; }

    public static void main(String[] args) {
        Order order = new Order(); // customer is null

        // This triggers a Helpful NullPointerException in Java 14+
        // Message: Cannot read field "address" because "order.customer" is null
        String city = order.customer.address.city;
        System.out.println(city);
    }
}
